"""Render the v3 measured-result addendum from the public JSON bundle."""
import json

def duration(seconds):
    n=round(seconds)
    h,n=divmod(n,3600);m,s=divmod(n,60)
    return (f'{h}h ' if h else '')+f'{m}m {s:02}s'

def build_v3(root, table, bar):
    d=json.loads((root/'v3-results.json').read_text())
    speed=d['serving']; panel=d['hard_panel']; colors=['#a8adb7','#ff4e5f','#39d0ff']
    labels=['Previous CIRU','CIRU v3','Halo MTP3']
    bar('v3-long-wall',labels,[speed[k]['65536']['request_s'] for k in speed],colors,'seconds','Cold 65536-token input plus 128-token output. Whole request; lower is faster.',2)
    bar('v3-panel-wall',labels,[r['wall']['after_ready_seconds']/60 for r in panel],colors,'minutes','Complete mixed benchmark panel, excluding model load. Lower is faster.',2)
    out=['''<div class="stats"><div class="stat primary"><span>V3 · 64K request time</span><b>23.9% <em>less</em></b><small>vs previous CIRU · 239.99 → 182.57 s</small></div><div class="stat"><span>V3 · mixed panel</span><b>25m 18s</b><small>13.6% less time than previous CIRU</small></div><div class="stat"><span>V3 · coding regression</span><b>20 / 20</b><small>HumanEval base and extended tests</small></div><div class="stat"><span>V3 · capacity verified</span><b>261,888</b><small>real input tokens + 128 generated</small></div></div>
<section id="v3-serving"><div class="section-head"><div><span class="eyebrow">01 / V3 serving · 09 SEP 2026</span><h2>Faster long-context requests</h2></div><a class="download" href="v3-serving.csv" download>Serving CSV ↓</a></div>
<p class="section-intro">Same CIRU weights, updated runtime and serving profile. At 64K, v3 reduces whole-request time by <strong>23.93%</strong>, raises prompt throughput by <strong>29.99%</strong>, and raises generation throughput by <strong>81.66%</strong> versus the previous CIRU runner. At 4K, whole-request time falls <strong>11.80%</strong>.</p>
<p class="context-note">All three arms ran sequentially on Ciru: Ryzen AI Max+ 395 / gfx1151, 128 GB unified memory, NixOS. Identical input token IDs, cold prompt cache, 128 output tokens, one slot and 262,144 context capacity. Each load has an excluded warmup. Previous CIRU is the locally qualified <strong>v2.0.1</strong> runner; it was not separately published as a tag.</p>''']
    rows=[]
    for ctx in ['4096','65536']:
        for k,cs in speed.items():
            r=cs[ctx];rows.append([f'{int(ctx):,}',k]+[f'{r[m]:.2f}' for m in ['PP','TG','TTFP_s','request_s']]+[r['rows']])
    out.append(table(['Input tokens','Profile','Prompt tok/s','Generation tok/s','First piece · s','Whole request · s','Requests'],rows,'Fixed-output serving experiment · arithmetic mean latency; pooled native PP and TG'))
    out.append('''<div class="chart-grid"><div class="chart-panel"><div class="chart-head"><div><h3>64K whole-request time</h3><p>Seconds · lower is faster</p></div><button class="export" data-export="v3-long-wall">PNG ↓</button></div><div id="v3-long-wall" class="chart" data-chart="v3-long-wall" role="img" aria-label="64K request time: previous CIRU 239.99 seconds, v3 182.57, Halo 254.37"></div></div><div class="chart-panel"><div class="chart-head"><div><h3>Complete mixed benchmark</h3><p>Minutes · includes tools and scoring</p></div><button class="export" data-export="v3-panel-wall">PNG ↓</button></div><div id="v3-panel-wall" class="chart" data-chart="v3-panel-wall" role="img" aria-label="Full mixed panel: previous CIRU 29 minutes 17 seconds, v3 25 minutes 18 seconds, Halo 24 minutes 34 seconds"></div></div></div>
<p class="footnote">Previous CIRU uses MTP6, b2048/u512; v3 uses MTP6, b1024/u1024. Both use F16 target KV and Q8 draft KV. Halo uses its unmodified Vulkan runner, Unsloth UD-Q4_K_XL target, EasiiX Q8 head and screened MTP3 profile. Halo generates faster at 4K; the small 4K whole-request difference is not a robust general v3 win. Three v3 loads, two Halo loads and one previous-CIRU load do not establish confidence intervals. This measures complete serving profiles, not runtime changes in isolation.</p>
<details><summary>Sampler, memory and full-capacity result</summary><p>Nonthinking, temperature 0.7, top-p 0.8, top-k 20, min-p 0, presence penalty 1.5, repeat penalty 1, frequency penalty 0, seed 123. EOS is honored; all reported requests produced 128 tokens. Native TG excludes the first output token; first-piece latency is the first streamed content-field event.</p>''')
    out.append(table(['Input','Profile','Peak system RAM · GiB','Max RAM increase · GiB','Peak GTT · GiB','Peak VRAM · GiB'],[[f'{int(ctx):,}',k]+[f'{r[m]:2.2f}' for m in ['peak_ram_GiB','max_delta_ram_GiB','peak_GTT_GiB','peak_VRAM_GiB']] for k,cs in speed.items() for ctx,r in cs.items()],'Sampled telemetry · RAM, GTT and VRAM overlap and must not be added'))
    cap=d['full_capacity']
    out.append(f'<p>The v3 capacity check completed <strong>261,888 input + 128 output tokens</strong>: {cap["PP"]:.2f} prompt tok/s, {cap["TG"]:.2f} generation tok/s, {cap["TTFP_s"]:.2f} s to first piece and {cap["request_s"]:.2f} s whole request. One CIRU-only request establishes serving capacity, not full-context answer accuracy or a 256K comparison with Halo.</p></details></section>')
    out.append('''<section id="v3-quality"><div class="section-head"><div><span class="eyebrow">02 / Task quality and elapsed time</span><h2>Mixed tasks, agents and long history</h2></div><a class="download" href="v3-benchmark-walltimes.csv" download>Wall times CSV ↓</a></div><p class="section-intro">The additional Ornith difficulty panel combines 22 short IFEval/GSM8K/HumanEval tasks, six Hermes scenarios repeated twice, eight hard tasks with a shared 63K-token history, and short/long coding health checks. It uses cases selected from earlier disagreements and failures; scores do not estimate general benchmark accuracy.</p>''')
    out.append(table(['Stage','Previous CIRU','CIRU v3','Halo MTP3'],[
        ['Complete panel, after readiness']+[duration(r['wall']['after_ready_seconds']) for r in panel],
        ['Model load, additional']+[duration(r['wall']['load_seconds']) for r in panel],
        ['Short scored stage']+[duration(r['short']['whole_stage_wall_seconds']) for r in panel],
        ['Hermes, two rounds combined']+[duration(sum(q['wall_seconds'] for q in r['hermes']['rounds'])) for r in panel],
        ['63K history seeding']+[duration(r['seed_seconds']) for r in panel],
        ['Long hard stage, history already loaded']+[duration(r['long']['wall_seconds']) for r in panel],
        ['All generated tokens']+[f'{r["output_tokens"]:,}' for r in panel],
    ],'Actual elapsed time, including applicable scorer/tool overhead. Stage rows are components of the complete panel; coding health and other overhead also contribute.'))
    out.append('<p class="footnote">V3 takes 13.59% less total time than previous CIRU, while Halo finishes 43.89 seconds sooner than v3. Long hard-stage time falls 42.98% versus previous CIRU, but output lengths differ. Short-stage time is effectively unchanged. These are complete workload timings, not equal-output generation speedups.</p>')
    out.append(table(['Profile','Short IFEval','Short GSM8K','Short HumanEval','Long IFEval','Long GSM8K','Long HumanEval'],[[r['profile']]+[f'{r[stage]["groups"][suite]["passed"]}/{r[stage]["groups"][suite]["total"]}' for stage in ['short','long'] for suite in ['ifeval','gsm8k','humaneval']] for r in panel],'Native first-sample scores · short and long tasks are different subsets'))
    out.append(table(['Profile','Hermes native full passes','Native mean points / 100','Reviewed end states'],[[r['profile'],f'{r["hermes"]["native_full_passes"]}/12',f'{r["hermes"]["native_mean_points"]:.2f}',f'{r["hermes"]["reviewed_end_states"]}/12'] for r in panel],'Six scenarios × two repetitions; reviewed end states do not replace native scores'))
    out.append('''<p class="footnote">V3 preserves the previous academic pass counts and improves Hermes native full passes from 7/12 to 11/12. Reviewed end states were 11/12, 12/12 and 12/12. Previous CIRU and Halo each have a memory-case wording artifact in the native grader; original grades are retained. All arms passed the short 10-task and long 8-task coding health checks, base and extended tests.</p>
<details><summary>Hard-panel protocol and review details</summary><p>One request at a time. Native short tasks: temperature 0, seed 15035, nonthinking, 32,768-token output allowance. Hermes: temperature 0.6, top-p 0.95, top-k 20, thinking enabled and full remaining context. Long tasks return to one shared 63K history; seeding is charged separately. First trajectories only, no answer repair. Two Hermes rounds expose variation without establishing a failure probability.</p><p>Short-task native generation: previous CIRU 38.44, v3 39.09, Halo 43.97 tok/s. Long hard generation: 21.75, 35.93 and 31.25 tok/s respectively. Different generated lengths and tool actions affect elapsed time. Instrumented, interrupted and canceled captures are excluded.</p><p><a href="v3-hard-panel.md">Full report and case-level review ↓</a> · <a href="v3-results.json">Structured measurements ↓</a></p></details></section>''')
    out.append('''<section id="v3-mtp"><div class="section-head"><div><span class="eyebrow">03 / MTP and regression checks</span><h2>Draft depth depends on the workload</h2></div></div><p class="section-intro">All four profiles passed <strong>20/20 HumanEval base and extended tests</strong> on the separate canonical tasks 0–19 panel. Previous CIRU and v3 MTP6 produced identical output token IDs; v3 reduces their summed request time by 6.39%. This is a bounded nonthinking regression test, not a full 164-task result.</p>''')
    out.append(table(['Profile','Generated tokens','Prompt tok/s','Generation tok/s','Sum of request times · s'],[[k,f'{r["generated_tokens"]:,}',f'{r["PP"]:.2f}',f'{r["TG"]:.2f}',f'{r["total_request_seconds"]:.2f}'] for k,r in d['coding20'].items()],'One sample per task, EvalPlus v0.1.10, 4096-token cap; truncations fail. Summed request time excludes grading.'))
    out.append('''<p class="footnote">MTP6 retains high-acceptance coding speed; MTP2 lowers it to 39.63 tok/s. On the lower-acceptance fixed-output fixture, optional MTP2 instead measured 13.62 s at 4K and 180.87 s at 64K (29.39 / 24.88 generation tok/s). It remains an option, not the general default. The target model verifies the full vocabulary at either depth.</p><p class="footnote">Recall checks recovered both keys with exact cached replay at approximately 8K and 64K for all three main arms. V3 passed 69 QSA mapping/state/guard cases, 33 ROCm operator reference cases, and 30 allocator tests with 198 assertions. A four-prefix diagnostic matched 15,892,480 F32 logits byte-for-byte; it does not establish universal equivalence or long-context task accuracy.</p></section>''')
    hist=d['historical_evalscope']; stages=hist['stages'][:5]; names=['ARC-Challenge','GPQA-Diamond','MMLU-Pro','GSM8K','IFEval strict']
    out.append('''<section id="evalscope-history"><div class="section-head"><div><span class="eyebrow">04 / Historical quality · 29 AUG 2026</span><h2>EvalScope baseline: 3h 17m 50s</h2></div></div><p class="section-intro">These are the completed <strong>H96, MTP depth-1</strong> results behind the earlier release’s EvalScope scores. They used the same released weights, one request at a time and uncapped natural-EOS generation. They have <strong>not been rerun on v3</strong>.</p>''')
    out.append(table(['Dataset','Pass count','Coverage','Measured wall time'],[[name,f'{hist["scores"][r["stage"]][0]}/{r["tasks"]}','Full dataset' if r['stage']=='arc' else 'Sampled subset',duration(r['seconds'])] for name,r in zip(names,stages)],'1,492 items · actual per-stage start/end timestamps, excluding setup and failed attempts'))
    out.append('''<p class="footnote">Quality stages together: 3h 17m 50s. Including the separate performance test: 3h 20m 46s. This is not the 25-minute v3 mixed panel above. No estimated v3 EvalScope wall time is presented as a measurement.</p><div class="downloads"><a href="v3-results.json" download>V3 + historical timing JSON ↓</a><a href="https://huggingface.co/jcbtc/Qwen3.8-Flash-CIRU-STRIX-IU4">Current model card ↗</a><a href="https://huggingface.co/jcbtc/Qwen3.8-Flash-CIRU-STRIX-IU4/blob/v3.0.0/benchmarks/v3.0.0/COMPARISON.md">V3 qualification ↗</a><a href="https://github.com/ciru-ai/Qwen3.8-Flash-CIRU-STRIX-IU4/releases/tag/v3.0.0">Runtime release ↗</a></div></section>''')
    return '\n'.join(out)
